17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.DayOfWeek;
20	import java.time.LocalDate;
21	import java.util.ArrayList;
22	import java.util.Collection;
23	import java.util.List;
24	
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.http.HttpHeaders;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ResponseEntity;
30	import org.springframework.samples.petclinic.mapper.IdentityKeyResolver;
31	import org.springframework.samples.petclinic.mapper.MembershipLevelResolver;
32	import org.springframework.samples.petclinic.mapper.OwnerMapper;
33	import org.springframework.samples.petclinic.mapper.PetMapper;
34	import org.springframework.samples.petclinic.mapper.Region;
35	import org.springframework.samples.petclinic.mapper.VisitMapper;
36	import org.springframework.samples.petclinic.model.Owner;
37	import org.springframework.samples.petclinic.model.Pet;
38	import org.springframework.samples.petclinic.model.Visit;
39	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitExceededException;
40	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerException;
41	import org.springframework.samples.petclinic.rest.advice.FutureRegistrationDateException;
42	import org.springframework.samples.petclinic.rest.advice.InvalidPostcodeException;
43	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
44	import org.springframework.samples.petclinic.rest.advice.OwnerCityFullException;
45	import org.springframework.samples.petclinic.rest.api.OwnersApi;
46	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
47	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
48	import org.springframework.samples.petclinic.rest.dto.PetDto;
49	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
50	import org.springframework.samples.petclinic.rest.dto.VisitDto;
51	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
52	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
53	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
54	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
55	import org.springframework.samples.petclinic.service.ClinicService;
56	import org.springframework.security.access.prepost.PreAuthorize;
57	import org.springframework.web.bind.annotation.CrossOrigin;
58	import org.springframework.web.bind.annotation.RequestMapping;
59	import org.springframework.web.bind.annotation.RestController;
60	import org.springframework.web.util.UriComponentsBuilder;
61	
62	import jakarta.transaction.Transactional;
63	
64	/**
65	 * @author Vitaliy Fedoriv
66	 */
67	
68	@RestController
69	@CrossOrigin(exposedHeaders = "errors, content-type")
70	@RequestMapping("/api")
71	public class OwnerRestControllerV1 implements OwnersApi {
72	
73	    /** Dedicated audit logger; a successful create emits a single line here with the new owner's key details. */
74	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
75	
76	    /** Maximum number of owners a single city may contain; creating an owner in a full city is rejected. */
77	    private static final int MAX_OWNERS_PER_CITY = 50;
78	
79	    /** Maximum number of owners that may be created in a single day; creating an owner past this cap is rejected. */
80	    private static final int MAX_OWNERS_PER_DAY = 100;
81	
82	    /** Once more than this many owners already exist for a day, a further create for that day is flagged as a bulk signup. */
83	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
84	
85	    private final ClinicService clinicService;
86	
87	    private final OwnerMapper ownerMapper;
88	
89	    private final PetMapper petMapper;
90	
91	    private final VisitMapper visitMapper;
92	
93	    private final TelephoneNormalizer telephoneNormalizer;
94	
95	    private final AddressNormalizer addressNormalizer;
96	
97	    private final EmailNormalizer emailNormalizer;
98	
99	    private final IdentityKeyResolver identityKeyResolver;
100	
101	    public OwnerRestControllerV1(ClinicService clinicService,
102	                                 OwnerMapper ownerMapper,
103	                                 PetMapper petMapper,
104	                                 VisitMapper visitMapper,
105	                                 TelephoneNormalizer telephoneNormalizer,
106	                                 AddressNormalizer addressNormalizer,
107	                                 EmailNormalizer emailNormalizer,
108	                                 IdentityKeyResolver identityKeyResolver) {
109	        this.clinicService = clinicService;
110	        this.ownerMapper = ownerMapper;
111	        this.petMapper = petMapper;
112	        this.visitMapper = visitMapper;
113	        this.telephoneNormalizer = telephoneNormalizer;
114	        this.addressNormalizer = addressNormalizer;
115	        this.emailNormalizer = emailNormalizer;
116	        this.identityKeyResolver = identityKeyResolver;
117	    }
118	
119	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
120	    @Override
121	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
122	        Collection<Owner> owners;
123	        if (lastName != null) {
124	            owners = this.clinicService.findOwnerByLastName(lastName);
125	        } else {
126	            owners = this.clinicService.findAllOwners();
127	        }
128	        if (owners.isEmpty()) {
129	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
130	        }
131	        owners.forEach(this::populateHouseholdMemberCount);
132	        List<OwnerDto> ownerDtos = owners.stream().map(this::toOwnerDto).toList();
133	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
134	    }
135	
136	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
137	    @Override
138	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
139	        Owner owner = this.clinicService.findOwnerById(ownerId);
140	        if (owner == null) {
141	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
142	        }
143	        populateHouseholdMemberCount(owner);
144	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
145	    }
146	
147	    /**
148	     * Maps an owner to its DTO and stamps on the derived {@code identityKey} (see
149	     * {@link IdentityKeyResolver#deriveIdentityKey}), which is not a stored field of the owner and so cannot be produced
150	     * by the mapper alone.
151	     *
152	     * @param owner the owner to map
153	     * @return the owner DTO carrying its identity key
154	     */
155	    private OwnerDto toOwnerDto(Owner owner) {
156	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
157	        ownerDto.setIdentityKey(identityKeyResolver.deriveIdentityKey(owner));
158	        return ownerDto;
159	    }
160	
161	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
162	    @Transactional
163	    @Override
164	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
165	        normalizeAndValidate(ownerFieldsDto);
166	        HttpHeaders headers = new HttpHeaders();
167	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
168	        populateDerivedFields(owner, ownerFieldsDto);
169	        requireUniqueIdentity(owner);
170	        this.clinicService.saveOwner(owner);
171	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
172	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
173	            MembershipLevelResolver.deriveMembershipLevel(owner.getEmail(), owner.getNamesakeCount()));
174	        populateHouseholdMemberCount(owner);
175	        OwnerDto ownerDto = toOwnerDto(owner);
176	        headers.setLocation(UriComponentsBuilder.newInstance()
177	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
178	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
179	    }
180	
181	    /**
182	     * Stamps onto a newly mapped owner every field derived at creation from the owner itself and from the owners that
183	     * already exist, in the order each field depends on. The {@code customerCode} is derived from the owner's own
184	     * fields (see {@link IdentityKeyResolver#deriveCustomerCode}); the {@code namesakeCount} (see
185	     * {@link #countNamesakes}) and {@code bulkSignupWarning} (see {@link #computeBulkSignupWarning}) are snapshots of
186	     * the existing owners taken before this owner is saved, so neither counts the new owner itself; and the shared
187	     * {@code householdId} is assigned last (see {@link #assignHouseholdId}), backfilling any existing household members
188	     * that lack it, so it is in place before {@link #requireUniqueIdentity} derives the identity key. The owner is
189	     * mutated in place; the caller applies the duplicate guard and saves it.
190	     *
191	     * @param owner          the newly mapped owner about to be saved
192	     * @param ownerFieldsDto the incoming owner payload
193	     */
194	    private void populateDerivedFields(Owner owner, OwnerFieldsDto ownerFieldsDto) {
195	        owner.setCustomerCode(identityKeyResolver.deriveCustomerCode(owner));
196	        owner.setNamesakeCount(countNamesakes(owner));
197	        owner.setBulkSignupWarning(computeBulkSignupWarning(owner.getRegistrationDate()));
198	        assignHouseholdId(owner, ownerFieldsDto);
199	    }
200	
201	    /**
202	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
203	     * saved. The address is first normalized to its canonical stored form and written back onto the payload; required
204	     * fields are then checked (so an address that is blank after normalization is rejected); the telephone is
205	     * normalized to its canonical stored form, written back onto the payload and rejected if another owner already uses
206	     * it; the email is canonicalized; and the registration date is resolved to its effective business day. The
207	     * effective registration date is the supplied value or, when none was supplied, the current server date; when it
208	     * falls on a weekend it is rolled forward to the following Monday and that adjusted date is written back onto the
209	     * payload, so every value derived from it (such as the membership number's year segment and the per-day limit)
210	     * uses the adjusted date. The payload is mutated in place so the caller can map and save it directly. Duplicate
211	     * detection is deferred: it runs once, against the derived {@code identityKey}, after the household id has been
212	     * assigned (see {@link #requireUniqueIdentity}).
213	     *
214	     * @param ownerFieldsDto the incoming owner payload, mutated in place
215	     * @throws MissingOwnerFieldsException if any required field is missing or blank
216	     */
217	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
218	        ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
219	        validateRequiredFields(ownerFieldsDto);
220	        validatePostcode(ownerFieldsDto);
221	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
222	        ownerFieldsDto.setTelephone(telephone);
223	        requireCityHasCapacity(ownerFieldsDto.getCity());
224	        LocalDate registrationDate = resolveRegistrationDate(ownerFieldsDto);
225	        ownerFieldsDto.setRegistrationDate(registrationDate);
226	        requireDailyLimitNotReached(registrationDate);
227	        String email = emailNormalizer.normalize(ownerFieldsDto.getEmail());
228	        ownerFieldsDto.setEmail(email);
229	    }
230	
231	    /**
232	     * Resolves an owner's effective registration date and rolls it onto a business day. The effective date is the value
233	     * supplied on the payload, or the current server date when none was supplied; when that date is a Saturday or
234	     * Sunday it is rolled forward to the following Monday. The returned date is always a business day. A supplied date
235	     * later than the current server date is rejected.
236	     *
237	     * @param ownerFieldsDto the incoming owner payload
238	     * @return the effective registration date rolled forward onto a business day
239	     * @throws FutureRegistrationDateException if a supplied registration date is later than the current server date
240	     */
241	    private LocalDate resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
242	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
243	        if (effective == null) {
244	            effective = LocalDate.now();
245	        }
246	        else if (effective.isAfter(LocalDate.now())) {
247	            throw new FutureRegistrationDateException(
248	                "the registration date must not be later than the current server date");
249	        }
250	        while (effective.getDayOfWeek() == DayOfWeek.SATURDAY || effective.getDayOfWeek() == DayOfWeek.SUNDAY) {
251	            effective = effective.plusDays(1);
252	        }
253	        return effective;
254	    }
255	
256	    /**
257	     * Rejects creating an owner once the maximum number of owners for the adjusted business day has already been
258	     * reached. The cap is 100, so when 100 or more existing owners carry the given adjusted {@code registrationDate} no
259	     * further owner may be created for that day.
260	     *
261	     * @param registrationDate the adjusted business-day registration date of the owner being created
262	     * @throws DailyOwnerLimitExceededException if 100 or more owners have already been created for that day
263	     */
264	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
265	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
266	            throw new DailyOwnerLimitExceededException(
267	                "the maximum number of owners for today has already been reached");
268	        }
269	    }
270	
271	    /**
272	     * Counts how many existing owners already carry the given adjusted business-day {@code registrationDate}. Invoked
273	     * before the new owner is saved, so the count reflects only owners that predate this create. Shared by
274	     * {@link #requireDailyLimitNotReached} (the hard per-day cap) and {@link #computeBulkSignupWarning} (the soft
275	     * warning threshold) so both express the same per-day count in one place.
276	     *
277	     * @param registrationDate the adjusted business-day registration date to count owners for
278	     * @return the number of existing owners registered on that day
279	     */
280	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
281	        return this.clinicService.findAllOwners().stream()
282	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
283	            .count();
284	    }
285	
286	    /**
287	     * Determines whether creating an owner for the given adjusted business-day registration date should carry a bulk
288	     * signup warning. The warning is raised once more than 80 owners already carry that {@code registrationDate},
289	     * i.e. this create is at least the 82nd for the day. Evaluated before the new owner is saved, so the count
290	     * reflects only owners that predate it.
291	     *
292	     * @param registrationDate the adjusted business-day registration date of the owner being created
293	     * @return {@code true} when more than 80 owners already exist for that day, {@code false} otherwise
294	     */
295	    private boolean computeBulkSignupWarning(LocalDate registrationDate) {
296	        return countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
297	    }
298	
299	    /**
300	     * Counts how many existing owners already share the given owner's first and last name, compared
301	     * case-insensitively. Invoked before the new owner is saved, so the result reflects only owners that predate this
302	     * create; it is zero when the owner's name is unique.
303	     *
304	     * @param owner the newly mapped owner about to be saved
305	     * @return the number of existing owners sharing the same first and last name (case-insensitively)
306	     */
307	    private int countNamesakes(Owner owner) {
308	        String firstName = owner.getFirstName();
309	        String lastName = owner.getLastName();
310	        return (int) this.clinicService.findAllOwners().stream()
311	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
312	                && lastName.equalsIgnoreCase(existing.getLastName()))
313	            .count();
314	    }
315	
316	    /**
317	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
318	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
319	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
320	     *
321	     * @param ownerFieldsDto the owner payload to validate
322	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
323	     */
324	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
325	        List<String> missingFields = new ArrayList<>();
326	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
327	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
328	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
329	        requireText(missingFields, "city", ownerFieldsDto.getCity());
330	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
331	        if (!missingFields.isEmpty()) {
332	            throw new MissingOwnerFieldsException(missingFields);
333	        }
334	    }
335	
336	    private void requireText(List<String> missingFields, String fieldName, String value) {
337	        if (value == null || value.isBlank()) {
338	            missingFields.add(fieldName);
339	        }
340	    }
341	
342	    /**
343	     * Validates an owner's optional {@code postcode} against its city's region. The postcode is validated only when
344	     * present; an owner created without one is accepted. Its 4-digit shape is already enforced by Bean Validation, so
345	     * this check only applies the region rule: when the city belongs to a known region (Sydney-&gt;NSW,
346	     * Melbourne-&gt;VIC, Brisbane-&gt;QLD) the postcode must fall within that region's inclusive range (NSW 2000-2099,
347	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
348	     *
349	     * @param ownerFieldsDto the incoming owner payload
350	     * @throws InvalidPostcodeException if a supplied postcode is out of range for its city's region
351	     */
352	    private void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
353	        String postcode = ownerFieldsDto.getPostcode();
354	        if (postcode == null) {
355	            return;
356	        }
357	        Region region = Region.forCity(ownerFieldsDto.getCity());
358	        if (region != null && !region.acceptsPostcode(Integer.parseInt(postcode))) {
359	            throw new InvalidPostcodeException(
360	                "postcode " + postcode + " is not valid for the city's region " + region.name());
361	        }
362	    }
363	
364	    /**
365	     * Rejects creating an owner whose whole derived {@code identityKey} (see
366	     * {@link IdentityKeyResolver#deriveIdentityKey}) equals that of an existing owner. This is the single, consolidated
367	     * duplicate check: the former separate telephone, email and household rules are all expressed through this one key,
368	     * so an owner is a duplicate only when its normalized telephone, email and {@code householdId} all match another
369	     * owner's. It runs after the household id has been assigned, so the key reflects the household the owner belongs to.
370	     *
371	     * @param owner the newly mapped owner about to be saved, with its household id already assigned
372	     * @throws DuplicateOwnerException if any existing owner already has the same identity key
373	     */
374	    private void requireUniqueIdentity(Owner owner) {
375	        String identityKey = identityKeyResolver.deriveIdentityKey(owner);
376	        boolean inUse = this.clinicService.findAllOwners().stream()
377	            .anyMatch(existing -> identityKey.equals(identityKeyResolver.deriveIdentityKey(existing)));
378	        if (inUse) {
379	            throw new DuplicateOwnerException("an owner with the same identity key already exists");
380	        }
381	    }
382	
383	    /**
384	     * Rejects creating an owner whose city (compared case-insensitively) already contains the maximum number of
385	     * owners. The cap is 50, so a city holding 50 or more owners is full and no further owner may be created there.
386	     *
387	     * @param city the city of the owner being created
388	     * @throws OwnerCityFullException if the city already contains 50 or more owners
389	     */
390	    private void requireCityHasCapacity(String city) {
391	        long cityOwners = this.clinicService.findAllOwners().stream()
392	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
393	            .count();
394	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
395	            throw new OwnerCityFullException("the owner's city already contains the maximum number of owners");
396	        }
397	    }
398	
399	    /**
400	     * Finds the existing owners that belong to the same household as the given payload, i.e. those sharing both its
401	     * last name and address. The last name is compared case-insensitively after collapsing runs of whitespace to a
402	     * single space and trimming; the address is compared in its normalized form (see {@link AddressNormalizer}), so
403	     * incidental formatting differences and abbreviation variants do not affect membership.
404	     *
405	     * @param ownerFieldsDto the incoming owner payload
406	     * @return the existing owners in the same household, in the order {@link ClinicService#findAllOwners()} returns
407	     *         them; empty when none match
408	     */
409	    private List<Owner> findHouseholdMembers(OwnerFieldsDto ownerFieldsDto) {
410	        String lastName = identityKeyResolver.collapseWhitespace(ownerFieldsDto.getLastName());
411	        String address = addressNormalizer.normalize(ownerFieldsDto.getAddress());
412	        return this.clinicService.findAllOwners().stream()
413	            .filter(existing -> identityKeyResolver.collapseWhitespace(existing.getLastName()).equalsIgnoreCase(lastName)
414	                && addressNormalizer.normalize(existing.getAddress()).equals(address))
415	            .toList();
416	    }
417	
418	    /**
419	     * Assigns the shared {@code householdId} for an owner joining an existing household. Only owners created with
420	     * {@code sharesHousehold} set to {@code true} that actually match an existing household (see
421	     * {@link #findHouseholdMembers}) are given an identifier; single owners keep a {@code null} household. The
422	     * identifier is derived deterministically from the household's last name and address (see
423	     * {@link IdentityKeyResolver#deriveHouseholdId}), so every member of the same household resolves to the same stable
424	     * value regardless of creation order. Existing members that predate the feature and still lack the identifier are
425	     * backfilled (see {@link #backfillHouseholdMembers}) so the whole household shares it.
426	     *
427	     * @param owner          the newly mapped owner about to be saved
428	     * @param ownerFieldsDto the incoming owner payload
429	     */
430	    private void assignHouseholdId(Owner owner, OwnerFieldsDto ownerFieldsDto) {
431	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
432	            return;
433	        }
434	        List<Owner> members = findHouseholdMembers(ownerFieldsDto);
435	        if (members.isEmpty()) {
436	            return;
437	        }
438	        String householdId =
439	            identityKeyResolver.deriveHouseholdId(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
440	        owner.setHouseholdId(householdId);
441	        backfillHouseholdMembers(householdId, members);
442	    }
443	
444	    /**
445	     * Stamps the shared {@code householdId} onto the existing members of a household that do not already carry it,
446	     * persisting each one that changes. Members that predate the feature (and so still lack the identifier) are brought
447	     * into line so the whole household shares the single value; members that already carry it are left untouched.
448	     *
449	     * @param householdId the shared household identifier
450	     * @param members     the existing owners in the household
451	     */
452	    private void backfillHouseholdMembers(String householdId, List<Owner> members) {
453	        for (Owner member : members) {
454	            if (!householdId.equals(member.getHouseholdId())) {
455	                member.setHouseholdId(householdId);
456	                this.clinicService.saveOwner(member);
457	            }
458	        }
459	    }
460	
461	    /**
462	     * Populates the owner's transient {@code householdMemberCount} with the number of owners that belong to its
463	     * household, i.e. those sharing the same non-null {@code householdId} (including the owner itself). An owner with no
464	     * household is counted as a household of one.
465	     *
466	     * @param owner the owner whose household size should be resolved
467	     */
468	    private void populateHouseholdMemberCount(Owner owner) {
469	        String householdId = owner.getHouseholdId();
470	        if (householdId == null) {
471	            owner.setHouseholdMemberCount(1);
472	            return;
473	        }
474	        long members = this.clinicService.findAllOwners().stream()
475	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
476	            .count();
477	        owner.setHouseholdMemberCount((int) members);
478	    }
479	
480	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
481	    @Override
482	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
483	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
484	        if (currentOwner == null) {
485	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
486	        }
487	        validatePostcode(ownerFieldsDto);
488	        currentOwner.setAddress(ownerFieldsDto.getAddress());
489	        currentOwner.setCity(ownerFieldsDto.getCity());
490	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
491	        currentOwner.setLastName(ownerFieldsDto.getLastName());
492	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
493	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
494	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
495	        this.clinicService.saveOwner(currentOwner);
496	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
497	    }
498	
499	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
500	    @Transactional
501	    @Override
502	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
503	        Owner owner = this.clinicService.findOwnerById(ownerId);
504	        if (owner == null) {
505	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
506	        }
507	        this.clinicService.deleteOwner(owner);
508	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
509	    }
510	
511	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
512	    @Override
513	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
514	        Owner owner = this.clinicService.findOwnerById(ownerId);
515	        if (owner == null) {
516	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
517	        }
518	        HttpHeaders headers = new HttpHeaders();
519	        Pet pet = petMapper.toPet(petFieldsDto);
520	        owner.setId(ownerId);
521	        pet.setOwner(owner);
522	        pet.getType().setName(null);
523	        this.clinicService.savePet(pet);
524	        PetDto petDto = petMapper.toPetDto(pet);
525	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
526	            .buildAndExpand(pet.getId()).toUri());
527	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
528	    }
529	
530	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
531	    @Override
532	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
533	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
534	        if (currentOwner != null) {
535	            Pet currentPet = this.clinicService.findPetById(petId);
536	            if (currentPet != null) {
537	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
538	                currentPet.setName(petFieldsDto.getName());
539	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
540	                this.clinicService.savePet(currentPet);
541	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
542	            }
543	        }
544	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
545	    }
546	
547	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
548	    @Override
549	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
550	        HttpHeaders headers = new HttpHeaders();
551	        Visit visit = visitMapper.toVisit(visitFieldsDto);
552	        Pet pet = new Pet();
553	        pet.setId(petId);
554	        visit.setPet(pet);
555	        this.clinicService.saveVisit(visit);
556	        VisitDto visitDto = visitMapper.toVisitDto(visit);
557	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
558	            .buildAndExpand(visit.getId()).toUri());
559	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
560	    }
561	
562	
563	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
