    20	
    21	/**
    22	 * Turns owner emails into the single canonical form that gets stored, returned and compared, so the REST controllers do
    23	 * not have to carry the email rules themselves.
    24	 *
    25	 * <p>A syntactically valid address is already enforced by Bean Validation on the request payload, so normalization only
    26	 * canonicalizes the value by lower-casing it. So {@code "Owner@Example.TEST"} becomes {@code "owner@example.test"}.
    27	 *
    28	 * <p>Unlike the address and telephone, an email is optional: a missing (blank or {@code null}) value is left untouched,
    29	 * so callers can uniformly treat a blank result as a missing email. The same canonical form is used both for the value
    30	 * that is stored and returned and for every email comparison (such as duplicate detection across existing owners), so
    31	 * incidental case differences never affect the outcome.
    32	 */
    33	@Component
    34	public class EmailNormalizer {
    35	
    36	    /**
    37	     * Normalizes an owner email into its canonical stored form by lower-casing it. A missing (blank or {@code null})
    38	     * email is returned untouched, since the field is optional. The normalized value is what gets stored and returned as
    39	     * {@code email}, and the same form is used when comparing an owner's email against those of existing owners.
    40	     *
    41	     * @param email the raw email value from the request, may be {@code null}
    42	     * @return the lower-cased email, or the original value when none was supplied
    43	     */
    44	    public String normalize(String email) {
    45	        if (email == null || email.isBlank()) {
    46	            return email;
    47	        }
    48	        return email.toLowerCase();
    49	    }
    50	}
