     1	package org.springframework.samples.petclinic.mapper;
     2	
     3	/**
     4	 * The canonical regions an owner's city can belong to. Modeling a region as a first-class type
     5	 * (rather than a bare string) gives the region-keyed rules a single home: each region owns the
     6	 * cities that resolve to it, so further region-scoped facts can hang off the same constant instead
     7	 * of being duplicated as a parallel city switch.
     8	 *
     9	 * <p>Kept in the {@code mapper} package alongside {@link LocalityResolver}, which turns a region
    10	 * into the {@code locality} string an owner is mapped with. Not a {@code @Mapper} type, so MapStruct
    11	 * ignores it.
    12	 */
    13	public enum Region {
    14	
    15	    NSW("Sydney", 2000, 2099),
    16	    VIC("Melbourne", 3000, 3099),
    17	    QLD("Brisbane", 4000, 4099);
    18	
    19	    private final String city;
    20	
    21	    private final int minPostcode;
    22	
    23	    private final int maxPostcode;
    24	
    25	    Region(String city, int minPostcode, int maxPostcode) {
    26	        this.city = city;
    27	        this.minPostcode = minPostcode;
    28	        this.maxPostcode = maxPostcode;
    29	    }
    30	
    31	    /**
    32	     * Returns whether the given (already 4-digit) postcode falls within this region's inclusive
    33	     * postcode range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
    34	     *
    35	     * @param postcode the numeric postcode value to test
    36	     * @return {@code true} when the postcode is within the region's range, {@code false} otherwise
    37	     */
    38	    public boolean acceptsPostcode(int postcode) {
    39	        return postcode >= this.minPostcode && postcode <= this.maxPostcode;
    40	    }
    41	
    42	    /**
    43	     * Returns the region whose inclusive postcode range contains the given postcode, or
    44	     * {@code null} when the postcode is absent, not a 4-digit number, or in no known range.
    45	     *
    46	     * @param postcode the owner's postcode, may be {@code null}
    47	     * @return the matching region, or {@code null} when the postcode maps to no known region
    48	     */
    49	    public static Region forPostcode(String postcode) {
    50	        if (postcode == null) {
    51	            return null;
    52	        }
    53	        int value;
    54	        try {
    55	            value = Integer.parseInt(postcode.trim());
    56	        }
    57	        catch (NumberFormatException ex) {
    58	            return null;
    59	        }
    60	        for (Region region : values()) {
    61	            if (region.acceptsPostcode(value)) {
    62	                return region;
    63	            }
    64	        }
    65	        return null;
    66	    }
    67	
    68	    /**
    69	     * Returns the region the given city belongs to, or {@code null} when the city is not in the
    70	     * table (including a {@code null} city).
    71	     *
    72	     * @param city the owner's city, may be {@code null}
    73	     * @return the matching region, or {@code null} when the city belongs to no known region
    74	     */
    75	    public static Region forCity(String city) {
    76	        if (city == null) {
    77	            return null;
    78	        }
    79	        for (Region region : values()) {
    80	            if (region.city.equals(city)) {
    81	                return region;
    82	            }
    83	        }
    84	        return null;
    85	    }
    86	}
