     1	package org.springframework.samples.petclinic.mapper;
     2	
     3	/**
     4	 * Derives an owner's {@code checkDigit}, the Luhn check digit computed over the
     5	 * digits contained in the owner's {@code customerCode}. Kept out of
     6	 * {@link OwnerMapper} so MapStruct does not mistake it for an implicit property
     7	 * mapping method.
     8	 */
     9	public final class CheckDigitResolver {
    10	
    11	    private CheckDigitResolver() {
    12	    }
    13	
    14	    /**
    15	     * Returns the Luhn check digit (0-9) computed over the digits contained in the
    16	     * given customer code. Non-digit characters are ignored.
    17	     *
    18	     * @param customerCode the owner's customer code, may be {@code null}
    19	     * @return the Luhn check digit, between 0 and 9 inclusive
    20	     */
    21	    public static int deriveCheckDigit(String customerCode) {
    22	        int sum = 0;
    23	        boolean dbl = true;
    24	        if (customerCode != null) {
    25	            for (int i = customerCode.length() - 1; i >= 0; i--) {
    26	                char c = customerCode.charAt(i);
    27	                if (c < '0' || c > '9') {
    28	                    continue;
    29	                }
    30	                int d = c - '0';
    31	                if (dbl) {
    32	                    d *= 2;
    33	                    if (d > 9) {
    34	                        d -= 9;
    35	                    }
    36	                }
    37	                sum += d;
    38	                dbl = !dbl;
    39	            }
    40	        }
    41	        return (10 - (sum % 10)) % 10;
    42	    }
    43	}
