184	        return errorResponse(e, HttpStatus.BAD_REQUEST, request, ERROR_INVALID_REQUEST, List.of("telephone"));
185	    }
186	
187	    /**
188	     * Handles {@link InvalidPostcodeException}, thrown when an owner supplies a 4-digit postcode that is out of range
189	     * for its city's region (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). Returns a {@code 400 Bad Request} reporting
190	     * the {@code postcode} field.
191	     *
192	     * @param e The {@link InvalidPostcodeException} to be handled
193	     * @param request {@link HttpServletRequest} object referring to the current request.
194	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
195	     */
196	    @ExceptionHandler(InvalidPostcodeException.class)
197	    @ResponseBody
198	    public ResponseEntity<ProblemDetail> handleInvalidPostcodeException(InvalidPostcodeException e, HttpServletRequest request) {
199	        logger.debug("Invalid postcode at {} {}: {}",
200	            request.getMethod(),
201	            request.getRequestURI(),
202	            e.getMessage());
203	        return errorResponse(e, HttpStatus.BAD_REQUEST, request, ERROR_INVALID_REQUEST, List.of("postcode"));
204	    }
205	
206	    /**
207	     * Handles {@link FutureRegistrationDateException}, thrown when a request to create an owner supplies a
208	     * {@code registrationDate} later than the current server date. Returns a {@code 400 Bad Request} reporting the
209	     * {@code registrationDate} field.
210	     *
211	     * @param e The {@link FutureRegistrationDateException} to be handled
212	     * @param request {@link HttpServletRequest} object referring to the current request.
213	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
214	     */
215	    @ExceptionHandler(FutureRegistrationDateException.class)
216	    @ResponseBody
217	    public ResponseEntity<ProblemDetail> handleFutureRegistrationDateException(FutureRegistrationDateException e, HttpServletRequest request) {
218	        logger.debug("Future registration date at {} {}: {}",
219	            request.getMethod(),
220	            request.getRequestURI(),
221	            e.getMessage());
222	        return errorResponse(e, HttpStatus.BAD_REQUEST, request, ERROR_INVALID_REQUEST, List.of("registrationDate"));
223	    }
224	
225	    /**
226	     * Handles {@link DuplicateOwnerException}, thrown when a request to create an owner carries a whole derived
227	     * {@code identityKey} (normalized telephone, email and household id) already used by another owner. This is the
228	     * single, consolidated duplicate rule. Returns a {@code 409 Conflict} reporting the {@code telephone},
229	     * {@code email} and {@code householdId} fields the key is composed of.
230	     *
231	     * @param e The {@link DuplicateOwnerException} to be handled
232	     * @param request {@link HttpServletRequest} object referring to the current request.
233	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
234	     */
235	    @ExceptionHandler(DuplicateOwnerException.class)
236	    @ResponseBody
237	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerException(DuplicateOwnerException e, HttpServletRequest request) {
238	        logger.debug("Duplicate owner identity at {} {}: {}",
239	            request.getMethod(),
240	            request.getRequestURI(),
241	            e.getMessage());
242	        return errorResponse(e, HttpStatus.CONFLICT, request, e.getMessage(),
243	            List.of("telephone", "email", "householdId"));
244	    }
245	
246	    /**
247	     * Handles {@link OwnerCityFullException}, thrown when a request to create an owner names a city that already
248	     * contains 50 or more owners (compared case-insensitively). Returns a {@code 409 Conflict} reporting the
249	     * {@code city} field.
250	     *
251	     * @param e The {@link OwnerCityFullException} to be handled
252	     * @param request {@link HttpServletRequest} object referring to the current request.
253	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
254	     */
255	    @ExceptionHandler(OwnerCityFullException.class)
256	    @ResponseBody
257	    public ResponseEntity<ProblemDetail> handleOwnerCityFullException(OwnerCityFullException e, HttpServletRequest request) {
