262	        return errorResponse(e, HttpStatus.CONFLICT, request, e.getMessage(), List.of("city"));
263	    }
264	
265	    /**
266	     * Handles {@link DailyOwnerLimitExceededException}, thrown when a request to create an owner arrives once 100 or
267	     * more owners have already been created today (compared by {@code registrationDate}). Returns a
268	     * {@code 429 Too Many Requests}.
269	     *
270	     * @param e The {@link DailyOwnerLimitExceededException} to be handled
271	     * @param request {@link HttpServletRequest} object referring to the current request.
272	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
273	     */
274	    @ExceptionHandler(DailyOwnerLimitExceededException.class)
275	    @ResponseBody
276	    public ResponseEntity<ProblemDetail> handleDailyOwnerLimitExceededException(DailyOwnerLimitExceededException e, HttpServletRequest request) {
277	        logger.debug("Daily owner creation limit reached at {} {}: {}",
