284	    /**
285	     * Builds the response body shared by the handlers that report a single business-rule violation: a
286	     * {@link ProblemDetail} for the given status carrying {@code detail} as its detail message and the offending field
287	     * names in its {@code errors} property.
288	     *
289	     * @param e the exception being handled, used to title the {@link ProblemDetail}
290	     * @param status the HTTP status to return
291	     * @param request {@link HttpServletRequest} object referring to the current request.
292	     * @param detail the human-readable detail message
293	     * @param errors the names of the fields the violation is reported against
294	     * @return a {@link ResponseEntity} carrying the problem detail and the given status
295	     */
296	    private ResponseEntity<ProblemDetail> errorResponse(Exception e, HttpStatus status, HttpServletRequest request,
297	                                                        String detail, List<String> errors) {
298	        ProblemDetail problemDetail = this.detailBuild(e, status, request.getRequestURL(), detail);
299	        problemDetail.setProperty("errors", errors);
300	        return ResponseEntity.status(status).body(problemDetail);
301	    }
